     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    private final Rooms rooms;
    13	    private final ReservationStore store;
    14	    private final PriceCalculator priceCalculator;
    15	    private final List<ReservationListener> listeners;
    16	
    17	    public ReservationService(
    18	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    19	            List<ReservationListener> listeners) {
    20	        this.rooms = rooms;
    21	        this.store = store;
    22	        this.priceCalculator = priceCalculator;
    23	        this.listeners = List.copyOf(listeners);
    24	    }
    25	
    26	    public synchronized Reservation create(NewReservation request) {
    27	        if (!request.checkOut().isAfter(request.checkIn())) {
    28	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    29	        }
    30	        if (request.guests() < 1) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    32	        }
    33	        Room room = rooms.find(request.roomNumber())
    34	                .orElseThrow(() -> new HotelException(
    35	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    36	        if (request.guests() > room.capacity()) {
    37	            throw new HotelException(
    38	                    ErrorCode.CAPACITY_EXCEEDED,
    39	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    40	        }
    41	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    42	            throw new HotelException(
    43	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    44	        }
    45	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    46	        return store.add(request, price);
    47	    }
    48	
    49	    public Reservation find(long reservationId) {
    50	        return store.find(reservationId)
    51	                .orElseThrow(() -> new HotelException(
    52	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    53	    }
    54	
    55	    /** The guest paid: the reservation is confirmed and the listeners are told. */
    56	    public synchronized Reservation confirm(long reservationId) {
    57	        Reservation reservation = find(reservationId);
    58	        if (reservation.status() != ReservationStatus.PENDING) {
    59	            throw notAllowed(reservation, "confirm");
    60	        }
    61	        reservation.confirmPayment();
    62	        store.update(reservation);
    63	        Room room = roomOf(reservation);
    64	        listeners.forEach(listener -> listener.confirmed(reservation, room));
    65	        return reservation;
    66	    }
    67	
    68	    /**
    69	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    70	     * reservation was never paid, so nothing comes back).
    71	     */
    72	    public synchronized Reservation cancel(long reservationId) {
    73	        Reservation reservation = find(reservationId);
    74	        if (reservation.status() != ReservationStatus.PENDING
    75	                && reservation.status() != ReservationStatus.CONFIRMED) {
    76	            throw notAllowed(reservation, "cancel");
    77	        }
    78	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    79	        BigDecimal refund = switch (reservation.ratePlan()) {
    80	            case STANDARD -> reservation.amountPaid();
    81	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    82	        };
    83	        reservation.cancel(refund);
    84	        store.update(reservation);
    85	        if (wasConfirmed) {
    86	            Room room = roomOf(reservation);
    87	            listeners.forEach(listener -> listener.confirmedReservationCancelled(reservation, room));
    88	        }
    89	        return reservation;
    90	    }
    91	
    92	    public synchronized Reservation checkIn(long reservationId) {
    93	        Reservation reservation = find(reservationId);
    94	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    95	            throw notAllowed(reservation, "check in");
    96	        }
    97	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    98	        store.update(reservation);
    99	        return reservation;
   100	    }
   101	
   102	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   103	    public synchronized ReservationReceipt checkOut(long reservationId) {
   104	        Reservation reservation = find(reservationId);
   105	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   106	            throw notAllowed(reservation, "check out");
   107	        }
   108	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   109	        store.update(reservation);
   110	        return new ReservationReceipt(reservation, roomOf(reservation));
   111	    }
   112	
   113	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   114	    public ReservationReceipt receiptCopy(long reservationId) {
   115	        Reservation reservation = find(reservationId);
   116	        if (!reservation.isPaid()) {
   117	            throw notAllowed(reservation, "issue a receipt for");
   118	        }
   119	        return new ReservationReceipt(reservation, roomOf(reservation));
   120	    }
   121	
   122	    private Room roomOf(Reservation reservation) {
   123	        return rooms.find(reservation.roomNumber()).orElseThrow();
   124	    }
   125	
   126	    private static HotelException notAllowed(Reservation reservation, String operation) {
   127	        return new HotelException(
   128	                ErrorCode.OPERATION_NOT_ALLOWED,
   129	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   130	    }
   131	}
